#!/usr/bin/env node
/**
 * check-site-mode.mjs — T-15 (Step 3 §9, AC-08): with SITE_MODE=public the
 * build FAILS while any displayed source has public_display_ok other than
 * 'yes'. SITE_MODE defaults to 'private' — the gate stays on and this check
 * is a no-op (it logs the mode and exits 0).
 *
 * Sources of truth (both generated by scripts/generate-indicators-registry.ts
 * and pinned by tests): data/indicator-audit.json (per-indicator licence
 * verdicts) — a Yahoo-sourced card (defect E-01) carries publicDisplayOk
 * 'no' and can never pass a public build. The world-markets / world-
 * currencies boards are EODHD/Yahoo-backed end to end, so in public mode
 * THIS SCRIPT ALSO FAILS unless data/site-mode-overrides.json explicitly
 * declares those boards hidden (a future public-mode work item, not this
 * one — recorded in STEP3_REPORT).
 *
 * Wired into apps/web's build: "build": "node ../../scripts/check-site-mode.mjs && vite build".
 */

import { readFileSync, existsSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const REPO = resolve(HERE, '..');

const mode = (process.env.SITE_MODE ?? 'private').toLowerCase();
if (mode !== 'public') {
  console.log(`[site-mode] SITE_MODE=${mode} — the private gate stays on; T-15 public-display check not applicable.`);
  process.exit(0);
}

console.log('[site-mode] SITE_MODE=public — verifying every displayed source is public-display-ok (T-15)…');

const audit = JSON.parse(readFileSync(resolve(REPO, 'data', 'indicator-audit.json'), 'utf8'));
const failures = [];
for (const entry of audit.indicators) {
  if (entry.publicDisplayOk !== 'yes') {
    failures.push(`${entry.id}: public_display_ok='${entry.publicDisplayOk}' (${entry.licenceName})`);
  }
}

// The markets/fx boards: EODHD (personal plan, owner only) + Yahoo (FTSE) —
// both 'no'. A public mode must explicitly declare them hidden via the
// overrides file; its absence is a failure (fail closed).
const overridesPath = resolve(REPO, 'data', 'site-mode-overrides.json');
if (!existsSync(overridesPath)) {
  failures.push('world-markets + world-currencies boards: EODHD/Yahoo-backed (public_display_ok no) and data/site-mode-overrides.json does not declare them hidden');
}

if (failures.length > 0) {
  console.error(`[site-mode] T-15 FAILED — ${failures.length} displayed source(s) are not public-display-ok:`);
  for (const f of failures) console.error(`  ✗ ${f}`);
  console.error('[site-mode] The public build is refused. Resolve the licences (or keep SITE_MODE=private).');
  process.exit(1);
}

console.error(
  '[site-mode] T-15 … unexpectedly passed: every indicator is public-ok but the markets/fx override check should still have run. Review scripts/check-site-mode.mjs.',
);
process.exit(1);
